#include "service_manager.h"
#include <string.h>
static int copy(char *d,size_t cap,const char *s,int required){size_t n;if(!s)s="";n=strlen(s);if((required&&!n)||n>=cap)return 0;memcpy(d,s,n+1);return 1;}
static int valid_id(const char *s){size_t i;if(!s||!s[0])return 0;for(i=0;s[i];i++){char c=s[i];if(!((c>='a'&&c<='z')||(c>='0'&&c<='9')||c=='-'||c=='_'||c=='.'))return 0;}return 1;}
void rtp_service_catalogue_init(rtp_service_catalogue *c){if(c)memset(c,0,sizeof(*c));}
const rtp_service_entry *rtp_service_find(const rtp_service_catalogue *c,const char *id){size_t i;if(!c||!id||c->count>RTP_SERVICE_MAX)return NULL;for(i=0;i<c->count;i++)if(!strcmp(c->entries[i].id,id))return &c->entries[i];return NULL;}
int rtp_service_register(rtp_service_catalogue *c,const rtp_service_descriptor *d){rtp_service_entry e;if(!c||!d||!valid_id(d->id)||!d->title||!d->description)return RTP_SERVICE_INVALID_ARGUMENT;if(c->count>RTP_SERVICE_MAX)return RTP_SERVICE_INVALID_ARGUMENT;if(c->count==RTP_SERVICE_MAX)return RTP_SERVICE_CAPACITY;if(rtp_service_find(c,d->id))return RTP_SERVICE_DUPLICATE;if(d->capabilities&~(RTP_SERVICE_CAN_START|RTP_SERVICE_CAN_STOP|RTP_SERVICE_CAN_AUTOSTART|RTP_SERVICE_READ_ONLY))return RTP_SERVICE_INVALID_DESCRIPTOR;if((d->capabilities&RTP_SERVICE_READ_ONLY)&&(d->capabilities&(RTP_SERVICE_CAN_START|RTP_SERVICE_CAN_STOP|RTP_SERVICE_CAN_AUTOSTART)))return RTP_SERVICE_INVALID_DESCRIPTOR;memset(&e,0,sizeof(e));if(!copy(e.id,sizeof(e.id),d->id,1)||!copy(e.title,sizeof(e.title),d->title,1)||!copy(e.description,sizeof(e.description),d->description,0)||!copy(e.conflict_group,sizeof(e.conflict_group),d->conflict_group,0))return RTP_SERVICE_INVALID_DESCRIPTOR;e.capabilities=d->capabilities;e.state=RTP_SERVICE_UNAVAILABLE;c->entries[c->count++]=e;return RTP_SERVICE_OK;}
int rtp_service_refresh(rtp_service_catalogue *c,const rtp_service_backend *b,void *ctx){size_t i;int failed=0;if(!c||!b||!b->query||c->count>RTP_SERVICE_MAX)return RTP_SERVICE_INVALID_ARGUMENT;for(i=0;i<c->count;i++){rtp_service_state state;int automatic=0;if(b->query(ctx,c->entries[i].id,&state,&automatic)!=0){c->entries[i].state=RTP_SERVICE_ERROR;failed=1;continue;}if(state<RTP_SERVICE_STOPPED||state>RTP_SERVICE_ERROR||automatic<0||automatic>1){c->entries[i].state=RTP_SERVICE_ERROR;failed=1;continue;}c->entries[i].state=state;c->entries[i].auto_start=automatic;}return failed?RTP_SERVICE_BACKEND_ERROR:RTP_SERVICE_OK;}
int rtp_service_start(rtp_service_catalogue *c,const char *id,const rtp_service_backend *b,void *ctx){size_t i;rtp_service_entry *target=NULL;if(!c||!id||!b||!b->start)return RTP_SERVICE_INVALID_ARGUMENT;for(i=0;i<c->count;i++)if(!strcmp(c->entries[i].id,id)){target=&c->entries[i];break;}if(!target)return RTP_SERVICE_NOT_FOUND;if(!(target->capabilities&RTP_SERVICE_CAN_START))return RTP_SERVICE_UNSUPPORTED;if(target->state==RTP_SERVICE_RUNNING)return RTP_SERVICE_OK;if(rtp_service_refresh(c,b,ctx)!=RTP_SERVICE_OK)return RTP_SERVICE_BACKEND_ERROR;if(target->conflict_group[0])for(i=0;i<c->count;i++){rtp_service_entry *other=&c->entries[i];if(other!=target&&other->state==RTP_SERVICE_RUNNING&&!strcmp(other->conflict_group,target->conflict_group))return RTP_SERVICE_CONFLICT;}if(b->start(ctx,id)!=0)return RTP_SERVICE_BACKEND_ERROR;target->state=RTP_SERVICE_RUNNING;return RTP_SERVICE_OK;}
int rtp_service_stop(rtp_service_catalogue *c,const char *id,const rtp_service_backend *b,void *ctx){size_t i;rtp_service_entry *e=NULL;if(!c||!id||!b||!b->stop)return RTP_SERVICE_INVALID_ARGUMENT;for(i=0;i<c->count;i++)if(!strcmp(c->entries[i].id,id)){e=&c->entries[i];break;}if(!e)return RTP_SERVICE_NOT_FOUND;if(!(e->capabilities&RTP_SERVICE_CAN_STOP))return RTP_SERVICE_UNSUPPORTED;if(e->state!=RTP_SERVICE_RUNNING)return RTP_SERVICE_OK;if(b->stop(ctx,id)!=0)return RTP_SERVICE_BACKEND_ERROR;e->state=RTP_SERVICE_STOPPED;return RTP_SERVICE_OK;}
int rtp_service_set_auto_start(rtp_service_catalogue *c,const char *id,int enabled,const rtp_service_backend *b,void *ctx){size_t i;rtp_service_entry *e=NULL;if(!c||!id||(enabled!=0&&enabled!=1)||!b||!b->set_auto_start)return RTP_SERVICE_INVALID_ARGUMENT;for(i=0;i<c->count;i++)if(!strcmp(c->entries[i].id,id)){e=&c->entries[i];break;}if(!e)return RTP_SERVICE_NOT_FOUND;if(!(e->capabilities&RTP_SERVICE_CAN_AUTOSTART))return RTP_SERVICE_UNSUPPORTED;if(b->set_auto_start(ctx,id,enabled)!=0)return RTP_SERVICE_BACKEND_ERROR;e->auto_start=enabled;return RTP_SERVICE_OK;}
